        'JDLA G検定 対策 第2弾。シラバス2024（2024年11月試験より適用）準拠。Set A が扱っていないテーマを中心に構成。個人情報保護法は範囲外（保有資格のため意図的に除外）。本試験の再現ではなく学習用オリジナル。',
        '#0B5CAB', 51)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('1. 人工知能とは', '#58a6ff', 0),
  ('2. 人工知能をめぐる動向', '#79c0ff', 1),
