COMMIT;
BEGIN;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q1', '機械に知能があるかを、人間の判定者が会話相手を人間と見分けられるかどうかで判断する方法はどれか。', NULL, '["チューリングテスト", "中国語の部屋", "フレーム問題", "シンボルグラウンディング問題"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "会話で人間と見分けられなければ知能ありとみなす、その判定方法の名前は？", "point": "「会話して人間と区別できなければ知能あり」とするテストなら、チューリングテスト。", "kid": "相手が人間か機械かを、文字のやり取りだけで当てさせる。見分けられなければ「その機械には知能があるとしよう」と決める判定方法。", "eg": "カーテン越しにチャットして、相手が人か機械か当てるゲーム。当てられなければ機械の勝ち＝知能ありと認める。", "terms": [["チューリングテスト", "会話して人間か機械か見分けられなければ、知能があると認める判定方法"], ["中国語の部屋", "正しく受け答えできても意味は理解していない、と反論する思考実験"]], "think": "「会話で人間と区別できるか」で知能を測るならチューリングテスト。中身の理解ではなく、外から見た振る舞いで判断する点がポイント。", "vs": "中国語の部屋はこのテストへの反論(受け答えできても理解とは限らない)、フレーム問題は考える範囲を絞れない難問、シンボルグラウンディング問題は記号と実物が結びつかない難問。どれも知能の判定方法ではない。", "usecase": "「AIが人間らしいか」を測る発想の原点。今のチャットAIの自然さを語るときの基準としてよく引き合いに出される。", "opt": ["正解。会話で人間と区別できなければ知能ありとみなす判定方法。", "受け答えできても意味は理解していないと反論する思考実験で、判定方法ではない。", "考える範囲を絞れない難問で、知能の判定方法ではない。", "記号と実物の意味が結びつかない難問で、判定方法ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q2', '「人工知能（Artificial Intelligence）」という言葉が初めて使われたとされる、1956年の研究者の集まりはどれか。', NULL, '["ダートマス会議", "第五世代コンピュータプロジェクト", "ロボット工学三原則の発表", "ILSVRC（画像認識コンテスト）"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "「人工知能」という言葉が初めて使われた1956年の集まりの名前は？", "point": "「人工知能(AI)」の語が生まれた1956年の会議なら、ダートマス会議。", "kid": "1956年、研究者が集まって「これからは“人工知能”という分野をやろう」と名付けた会議。AIという言葉が生まれた場。", "eg": "新しい学問に名前をつけた“旗揚げ集会”のようなもの。ここで「人工知能」という看板が初めて掲げられた。", "terms": [["ダートマス会議", "1956年、マッカーシーらが開いた会議。ここで「人工知能」という言葉が初めて使われた"], ["第1次AIブーム", "この会議の後に始まった、探索や推論で問題を解く最初のブーム"]], "think": "「AIという言葉の始まり・1956年」ならダートマス会議。技術そのものではなく、分野の名付けの出来事だと押さえる。", "vs": "第五世代コンピュータは1980年代の日本の国家プロジェクト、ロボット工学三原則はSF作家アシモフの創作、ILSVRCは2010年代の画像認識コンテスト。どれもAIの語源となった会議ではない。", "usecase": "AIの歴史の出発点。ブームの流れ(第1次→第2次→第3次)を語るときの起点として押さえる。", "opt": ["正解。1956年、「人工知能」という言葉が初めて使われた会議。", "1980年代の日本の国家プロジェクトで、AIの語源の会議ではない。", "SF作家が作った創作上の原則で、実在の会議ではない。", "2010年代の画像認識コンテストで、AIの語源とは時代が違う。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q3', '第1次AIブームの限界を象徴する言葉で、迷路やパズルのように単純化された問題は解けても、複雑な現実の問題には歯が立たなかったことを指す語はどれか。', NULL, '["トイ・プロブレム", "フレーム問題", "組合せ爆発", "次元の呪い"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "単純化された問題は解けても現実の複雑な問題は解けなかった、第1次ブームの限界を指す語は？", "point": "「おもちゃのように単純化した問題しか解けなかった」なら、トイ・プロブレム。", "kid": "迷路や積み木のように、きれいに単純化された問題なら解ける。でも現実のごちゃごちゃした問題には歯が立たない。この限界を「おもちゃの問題」と呼んだ。", "eg": "教科書の練習問題は解けるのに、実際の仕事の複雑な課題になると手も足も出ない、あの状態。", "terms": [["トイ・プロブレム", "迷路やパズルのように単純化された問題。第1次ブームのAIはこれしか解けなかった"], ["組合せ爆発", "選択肢が増えると調べる場合の数が爆発的に増え、計算が追いつかなくなる現象"]], "think": "「単純化された問題は解けたが現実は無理」という第1次ブームの限界ならトイ・プロブレム。原因の一つが組合せ爆発。", "vs": "フレーム問題は考える範囲を絞れない難問、組合せ爆発は場合の数が急増する現象、次元の呪いは項目が多すぎてデータがスカスカになる問題。どれも「おもちゃの問題」そのものではない。", "usecase": "「なぜ最初のAIブームが冷めたか」の説明に使う。単純な世界と現実の複雑さのギャップを示す言葉。", "opt": ["正解。単純化された問題しか解けなかった第1次ブームの限界を指す。", "考える範囲を絞れない難問で、単純化された問題という意味ではない。", "場合の数が急増する現象で、限界そのものを指す言葉ではない。", "項目が多すぎてデータがスカスカになる別の問題。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q4', 'AIが自分自身を上回るAIを作り出せるようになり、技術の進歩が予測不能なほど加速するとされる転換点を指す語はどれか。', NULL, '["シンギュラリティ（技術的特異点）", "ムーアの法則", "AI効果", "チューリングポイント"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIが自分を超えるAIを生み、進歩が予測不能に加速するとされる転換点は？", "point": "「AIが人間の知能を超え、進歩が爆発的に加速する未来の分岐点」なら、シンギュラリティ。", "kid": "AIが「自分より賢いAI」を作れるようになると、賢さがねずみ算式に跳ね上がる。その先は人間には予測できない——その転換点のこと。未来予測の概念で、まだ起きていない。", "eg": "雪だるまが坂を転がり始めると一気に巨大化して止められなくなる、あのイメージ。賢さが自己増殖する分岐点。", "terms": [["シンギュラリティ（技術的特異点）", "AIが自分を超えるAIを生み、知能が爆発的に伸びるとされる未来の転換点"], ["ムーアの法則", "半導体の性能がほぼ一定ペースで向上するという経験則"]], "think": "「AIが人間を超えて進歩が加速する未来の分岐点」ならシンギュラリティ。実在の技術ではなく将来予測の概念。", "vs": "ムーアの法則は半導体の性能向上の経験則、AI効果は仕組みが分かると知能扱いされなくなる心理、チューリングポイントは正式な用語ではない造語。", "usecase": "AIの将来リスクや期待を語るときの中心的な言葉。過度な期待や不安を切り分けるのに、概念として知っておく。", "opt": ["正解。AIが人間を超え進歩が爆発的に加速するとされる転換点。", "半導体の性能向上の経験則で、知能の転換点の話ではない。", "仕組みが分かると知能扱いされなくなる心理で、未来の転換点ではない。", "正式な用語ではない造語で、この転換点を指さない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q5', '探索木をたどるとき、まず出発点に近い節点をすべて調べ、次に一段深い節点をすべて調べる、というように浅い方から順に探す方法はどれか。', NULL, '["幅優先探索", "深さ優先探索", "山登り法", "焼きなまし法"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "浅いところから順に、同じ深さを全部調べてから次へ進む探索方法は？", "point": "「近いところから順に、同じ深さを全部調べてから次へ」なら、幅優先探索。", "kid": "出発点から近い場所を全部調べ、次に一歩遠い場所を全部調べる…と、輪を広げるように浅い方から探すやり方。", "eg": "池に石を落としたときの波紋のように、中心から一枚ずつ外側へ調べていく探し方。", "terms": [["幅優先探索", "出発点に近い順に、同じ深さの節点を全部調べてから次の深さへ進む方法"], ["深さ優先探索", "一本道をとことん奥まで進み、行き止まったら戻る逆の方法"]], "think": "「浅い層を全部見てから次の層へ」なら幅優先。「まず深く潜って行き止まりで戻る」なら深さ優先。進む順で見分ける。", "vs": "深さ優先探索は深く潜る逆のやり方、山登り法は今より良くなる方へ進み続ける最適化、焼きなまし法はわざと悪い方へも動いて局所解を抜ける最適化。どれも浅い順に全部調べる探索ではない。", "usecase": "一番近い(手数の少ない)解を確実に見つけたいときに使う。迷路の最短手数や、SNSで「何人たどれば繋がるか」などで効く。", "opt": ["正解。浅い層を全部調べてから次の層へ進むのが幅優先探索。", "一本道を深く潜る逆のやり方で、浅い順ではない。", "今より良くなる方へ進み続ける最適化で、木を網羅する探索ではない。", "わざと悪い方へも動く最適化で、浅い順に調べる探索ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q6', 'ゲームの先読みで、探索しても結果に影響しないと分かった枝を途中で切り捨て、無駄な計算を減らす手法はどれか。', NULL, '["αβ法（アルファ・ベータ枝刈り）", "誤差逆伝播法", "主成分分析", "ブートストラップ法"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "先読みで、調べても無駄と分かった枝を途中で切り捨てて計算を減らす手法は？", "point": "「先読みで、明らかに無駄な枝を途中で切って計算を減らす」なら、αβ法（枝刈り）。", "kid": "将棋やチェスの先読みで、「この手はどう転んでも損」と分かった枝は、それ以上調べずに切り捨てる。無駄な計算を省いて速くする工夫。", "eg": "買い物で「この店は明らかに高い」と分かった時点で、棚を全部見ずに次の店へ行く、あの判断。見るだけ無駄な所を飛ばす。", "terms": [["αβ法（アルファ・ベータ枝刈り）", "ゲーム木の探索で、結果に影響しない枝を早めに切り捨てて計算量を減らす手法"], ["ミニマックス法", "相手が最善を尽くす前提で、自分の最善手を選ぶ先読みの基本"]], "think": "「先読みで無駄な枝を切る」ならαβ法。全部読むミニマックス法の計算を減らす改良、と押さえる。", "vs": "誤差逆伝播法はニューラルネットの学習手法、主成分分析は次元削減、ブートストラップ法は重複ありでデータを選び直す方法。どれもゲーム木の枝刈りではない。", "usecase": "将棋・チェス・オセロなどのゲームAIで、限られた時間により深く読むために使う。無駄を省いて先読みを深める土台。", "opt": ["正解。結果に影響しない枝を切り捨てて計算を減らすのがαβ法。", "ニューラルネットの学習手法で、ゲーム木の枝刈りではない。", "次元削減の手法で、探索の枝刈りとは関係ない。", "重複ありでデータを選び直す方法で、枝刈りではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q7', '囲碁AIのAlphaGoでも使われた、次の手をランダムに何度も試して勝率を見積もり、有望な手を選ぶ探索手法はどれか。', NULL, '["モンテカルロ木探索", "深さ優先探索", "k近傍法", "サポートベクターマシン"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "ランダムな試行を繰り返して手の勝率を見積もり、有望な手を選ぶ探索手法は？", "point": "「ランダムに何度も試して勝率で手を評価する」なら、モンテカルロ木探索。", "kid": "この手を打ったら勝てるか？を、その先をランダムに何回も打ちきってみて勝率で見積もる。勝率の高い手を選ぶ、という探索のやり方。", "eg": "サイコロを何千回も振って出目の傾向をつかむように、ランダムな試行を大量に重ねて「良さそうな手」を見つける。", "terms": [["モンテカルロ木探索", "手の先をランダムに多数シミュレーションし、勝率で手の良さを見積もる探索手法"], ["AlphaGo", "この手法と深層学習を組み合わせ、プロ棋士に勝った囲碁AI"]], "think": "「ランダム試行を大量に重ねて勝率で評価」ならモンテカルロ木探索。全部を律儀に読むのではなく、サンプルで見積もるのが特徴。", "vs": "深さ優先探索は一本道を深く潜る探索、k近傍法は近所の正解で多数決する分類、サポートベクターマシンは分ける線を学ぶ分類。どれもランダム試行で勝率を見積もる探索ではない。", "usecase": "囲碁のように選択肢が多すぎて全部読めないゲームで力を発揮した。AlphaGoの中核技術の一つ。", "opt": ["正解。ランダムな試行を重ねて勝率で手を評価するのがモンテカルロ木探索。", "一本道を深く潜る探索で、ランダム試行で勝率を見積もる手法ではない。", "近所の正解で多数決する分類で、ゲームの探索ではない。", "分ける線を学ぶ分類で、勝率を見積もる探索ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q8', '「鳥は動物である」「ペンギンは鳥である」のように、概念どうしの関係を線でつないで知識を表す方法はどれか。', NULL, '["意味ネットワーク", "ニューラルネットワーク", "決定木", "混同行列"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "概念どうしの関係を線でつないで知識を表す方法は？", "point": "「概念を『〜は〜である』の関係で線でつないで知識を表す」なら、意味ネットワーク。", "kid": "「鳥は動物」「ペンギンは鳥」のように、言葉どうしを“〜は〜である”の矢印でつないで、知識を図にする方法。第2次ブームの知識表現の一つ。", "eg": "家系図のように、概念どうしを線でつないで「誰が誰の仲間か」を一目で分かるようにした図。", "terms": [["意味ネットワーク", "概念(ノード)を「is-a(〜である)」などの関係(リンク)でつないで知識を表す方法"], ["ニューラルネットワーク", "脳の神経細胞をまねた、数値の重みで学習する別物のネットワーク"]], "think": "「概念を関係でつないで知識を図にする」なら意味ネットワーク。名前が似たニューラルネットワーク(学習の仕組み)と混同しない。", "vs": "ニューラルネットワークは重みを学習する仕組み、決定木は条件分岐で予測する手法、混同行列は判定結果の集計表。どれも概念の関係を表す知識表現ではない。", "usecase": "知識をコンピュータに持たせる古典的な方法。今のナレッジグラフ(検索やレコメンドで使う知識の網)の考え方の源流。", "opt": ["正解。概念を関係の線でつないで知識を表すのが意味ネットワーク。", "重みを学習する脳まねのネットワークで、知識を図にする方法ではない。", "条件分岐で予測する手法で、概念の関係を表すものではない。", "判定結果の集計表で、知識表現ではない。"]}'::jsonb, 1
