SELECT s.id, c.id, 'g-kentei-b-q14', '2つのグループを分ける境界線を引くとき、境界と最も近いデータとの余白（マージン）ができるだけ広くなるように引く手法はどれか。', NULL, '["サポートベクターマシン（SVM）", "k-means法", "主成分分析", "ナイーブベイズ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "2グループを分ける境界を、余白(マージン)が最大になるように引く手法は？", "point": "「境界と一番近いデータとの余白(マージン)を最大にして分ける」なら、SVM。", "kid": "2つのグループの間に線を引くとき、どちらのグループからもなるべく離れた“真ん中”に引く。余白を広く取るほど、新しいデータでも間違えにくい。", "eg": "2つのチームの間に道を作るとき、どちらの陣地にもギリギリ寄らず、一番広く空いた真ん中に引く、あの引き方。", "terms": [["サポートベクターマシン（SVM）", "境界と最も近いデータとの余白(マージン)が最大になるよう分ける分類手法"], ["マージン", "境界と、一番近いデータとの間の余白。これを最大にするのがSVMの狙い"]], "think": "「余白(マージン)を最大にして分ける」ならSVM。ただ分ければよいのではなく、“一番安全な真ん中”に境界を引く点がポイント。", "vs": "k-means法は正解なしのグループ分け、主成分分析は次元削減、ナイーブベイズは確率で分類する別手法。どれもマージン最大化で境界を引くものではない。", "usecase": "データが少なめでも高い精度が出しやすく、文字認識や文書分類などで長く使われてきた定番の分類手法。", "opt": ["正解。余白(マージン)を最大にして分けるのがSVM。", "正解なしのグループ分けで、余白を最大化する境界の話ではない。", "次元削減の手法で、分類の境界を引くものではない。", "確率で分類する別手法で、マージン最大化ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='3. 機械学習の概要'
