INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q15', 'モデルが単純すぎて的外れになる誤りと、複雑すぎてデータのブレに振り回される誤りは、一方を抑えると他方が増えやすい。この関係を指す語はどれか。', NULL, '["バイアスとバリアンスのトレードオフ", "次元の呪い", "データリーケージ", "コールドスタート問題"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "単純すぎる誤り(バイアス)と複雑すぎる誤り(バリアンス)は両立しにくい、この関係の名前は？", "point": "「単純すぎる誤りと複雑すぎる誤りが、あちらを立てればこちらが立たず」なら、バイアスとバリアンスのトレードオフ。", "kid": "モデルが単純すぎると的外れ(バイアス大＝未学習)。複雑すぎるとデータの偶然のブレまで拾って本番に弱い(バリアンス大＝過学習)。片方を抑えるともう片方が増えがちで、ちょうど良い所を探す。", "eg": "服のサイズ選び。大きすぎ(ゆるゆる)も小さすぎ(きつきつ)もダメで、ちょうど良い所を探すのと同じ。", "terms": [["バイアス", "モデルが単純すぎて的を外す誤り。大きいと未学習"], ["バリアンス", "モデルが複雑すぎてデータのブレに振り回される誤り。大きいと過学習"]], "think": "「単純すぎ(バイアス)と複雑すぎ(バリアンス)のどちらも誤りで、両立しにくい」ならこのトレードオフ。未学習と過学習を同じ軸で捉えた見方。", "vs": "次元の呪いは項目が多すぎてデータがスカスカになる問題、データリーケージは答えが訓練に漏れる失敗、コールドスタート問題はおすすめの初期データ不足。どれも2種類の誤りの綱引きではない。", "usecase": "モデルの複雑さをどこまで上げるか(木の深さ、層の数など)を決める指針。「未学習でも過学習でもない所」を狙う調整の土台。", "opt": ["正解。単純すぎる誤りと複雑すぎる誤りが両立しにくい関係を指す。", "項目が多すぎてデータがスカスカになる問題で、2種類の誤りの綱引きではない。", "答えが訓練に漏れる失敗で、この関係とは別。", "おすすめの初期データ不足の問題で、この関係とは関係ない。"]}'::jsonb, 1
