INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q16', '手元のデータを「訓練用」と「テスト用」に一度だけ分け、訓練用で学習し、テスト用で成績を測る、最もシンプルな評価方法はどれか。', NULL, '["ホールドアウト検証", "k分割交差検証", "グリッドサーチ", "アンサンブル学習"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "データを訓練用とテスト用に一度だけ分けて評価する、最もシンプルな方法は？", "point": "「訓練用とテスト用に一度だけ分けて評価する」なら、ホールドアウト検証。", "kid": "手元のデータを「練習用」と「本番テスト用」に一回だけ分ける。練習用で覚えさせ、テスト用で初見の成績を測る。一番シンプルな評価のやり方。", "eg": "問題集を「練習ページ」と「模試ページ」に分けて、模試ページで実力を測る、あの方式。", "terms": [["ホールドアウト検証", "データを訓練用とテスト用に一度だけ分けて評価する方法"], ["k分割交差検証", "分け方を変えて何度も測り平均する、より信頼性の高い方法"]], "think": "「一度だけ訓練とテストに分けて終わり」ならホールドアウト。分け直して何度も測り平均するk分割交差検証より手軽だが、分け方のたまたまに左右されやすい。", "vs": "k分割交差検証は分け直して平均する方法、グリッドサーチは設定の組合せを総当たりする方法、アンサンブル学習は複数モデルを組み合わせる方法。どれも一度きりの分割による評価そのものではない。", "usecase": "データが十分ある場合の手軽な評価に使う。少ないデータで安定して測りたいときは、より丁寧なk分割交差検証を選ぶ。", "opt": ["正解。訓練用とテスト用に一度だけ分けて評価するのがホールドアウト検証。", "分け直して何度も測り平均する方法で、一度きりではない。", "設定の組合せを総当たりする方法で、評価の分け方そのものではない。", "複数モデルを組み合わせる方法で、データの分割による評価ではない。"]}'::jsonb, 1
