INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q17', '身長(cm)と体重(kg)のように単位も桁も違う項目を、そのまま使うと桁の大きい項目に結果が引っ張られる。これを防ぐため各項目のスケールをそろえる前処理はどれか。', NULL, '["標準化（スケールをそろえる正規化）", "アノテーション", "データ拡張", "次元削減"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "単位も桁も違う項目のスケールをそろえて、桁の大きい項目に引っ張られないようにする前処理は？", "point": "「桁や単位の違う項目のスケールをそろえる前処理」なら、標準化(正規化)。", "kid": "身長(150〜180)と体重(50〜80)をそのまま混ぜると、数字の大きい身長ばかり効いてしまう。だから各項目を同じものさしにそろえてから使う。この下ごしらえが標準化。", "eg": "各教科の点数を、満点も難易度も違うまま合計せず、偏差値にそろえてから比べる、あの発想。", "terms": [["標準化", "各項目を平均0・ばらつき1くらいにそろえ、桁の違いで結果が偏らないようにする前処理"], ["特徴量", "モデルに入れる各項目(身長・体重など)のこと"]], "think": "「桁や単位の違いをそろえる下ごしらえ」なら標準化(正規化)。距離や大きさを使う手法(k近傍法・SVMなど)ほど、やらないと結果が偏る。", "vs": "アノテーションは正解ラベルを付ける作業、データ拡張はデータを水増しする手法、次元削減は項目の数を減らす手法。どれもスケールをそろえる前処理そのものではない。", "usecase": "距離や大きさで判断する手法の前にほぼ必須の下ごしらえ。やるだけで精度が安定することが多い、地味だが効く工程。", "opt": ["正解。桁や単位の違う項目のスケールをそろえる前処理。", "正解ラベルを付ける作業で、スケールをそろえる前処理ではない。", "データを水増しする手法で、スケール調整ではない。", "項目の数を減らす手法で、スケールをそろえる処理とは別。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='3. 機械学習の概要'
