INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q18', '入力がマイナスなら0、プラスならそのまま通す、というシンプルな活性化関数で、勾配消失を起こしにくく深い層でよく使われるものはどれか。', NULL, '["ReLU", "シグモイド関数", "ソフトマックス関数", "ステップ関数"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "マイナスは0・プラスはそのまま通す、勾配消失を起こしにくい活性化関数は？", "point": "「マイナスは0、プラスはそのまま。勾配消失を起こしにくい」なら、ReLU。", "kid": "各層で通す値を加工する部品(活性化関数)の一つ。マイナスは0にし、プラスはそのまま素通し。傾きが痩せないので、深い層でも学習の「直してね」の合図が消えにくい。", "eg": "水道の逆止弁のように、マイナス方向は止めてプラス方向はそのまま通す、シンプルな弁。", "terms": [["ReLU", "入力がマイナスなら0、プラスならそのまま通す活性化関数。勾配消失に強い"], ["シグモイド", "出力を0〜1に押し込む活性化関数。傾きが小さく深い層で勾配が消えやすい"]], "think": "「マイナスは0・プラスは素通しで勾配が消えにくい」ならReLU。傾きが痩せて勾配消失を起こしやすいシグモイドの代わりに使う、と押さえる。", "vs": "シグモイドは0〜1に押し込む活性化関数(勾配が消えやすい)、ソフトマックスは出口で合計100%の確率にする関数、ステップ関数は0か1に切り替えるだけで学習に使いにくい。どれもReLUではない。", "usecase": "今のディープラーニングの中間層で最も標準的に使われる。深いネットワークが学習できるようになった立役者の一つ。", "opt": ["正解。マイナスは0・プラスは素通しで勾配が消えにくいのがReLU。", "0〜1に押し込む関数で、傾きが小さく勾配が消えやすい。", "出口で合計100%の確率にする関数で、中間層の素通しとは役割が違う。", "0か1に切り替えるだけで、学習の勾配が得られず使いにくい。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='4. ディープラーニングの概要'
