SELECT s.id, c.id, 'g-kentei-b-q19', '各層に入ってくる値のばらつきを層ごとにそろえることで、学習を安定させ速くする手法はどれか。', NULL, '["バッチ正規化", "ドロップアウト", "データ拡張", "早期終了"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "各層に入る値のばらつきをそろえて、学習を安定・高速にする手法は？", "point": "「各層に入る値のばらつきを層ごとにそろえて学習を安定させる」なら、バッチ正規化。", "kid": "層を通るうちに、入ってくる値の大きさやばらつきがバラバラになると学習しにくい。そこで層ごとに値を整えて(平均やばらつきをそろえて)、学習を安定させ速くする工夫。", "eg": "リレーで各走者にバトンを毎回同じ高さで渡すように、各層への“渡し方”を一定にそろえて流れを乱さない、あの発想。", "terms": [["バッチ正規化", "各層に入る値を、まとまり(バッチ)ごとに平均やばらつきをそろえて学習を安定させる手法"], ["内部共変量シフト", "学習中に各層への入力の分布がずれていく現象。バッチ正規化が抑えるとされる"]], "think": "「各層に入る値のばらつきをそろえる」ならバッチ正規化。ノードを休ませるドロップアウト(過学習対策)とは目的が違う。", "vs": "ドロップアウトはノードをランダムに休ませる過学習対策、データ拡張はデータを水増しする手法、早期終了は成績が悪化し始めたら学習を止める手法。どれも各層の値をそろえる正規化ではない。", "usecase": "深いネットワークの学習を安定させ、学習率を大きめにして速く進めるのに効く。今の多くのモデルで標準的に組み込まれる。", "opt": ["正解。各層に入る値のばらつきをそろえて学習を安定させるのがバッチ正規化。", "ノードをランダムに休ませる過学習対策で、値をそろえる正規化ではない。", "データを水増しする手法で、層の値をそろえるものではない。", "学習を途中で止める手法で、値の正規化ではない。"]}'::jsonb, 1
