INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q20', '全データではなく、一部を小分け（ミニバッチ）にして少しずつ重みを更新していく、基本的な最適化のやり方はどれか。', NULL, '["確率的勾配降下法（SGD）", "主成分分析", "k近傍法", "焼きなまし法"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "データを小分け(ミニバッチ)にして少しずつ重みを更新する、基本の最適化は？", "point": "「データを小分けにして少しずつ重みを更新する」なら、確率的勾配降下法(SGD)。", "kid": "AIの学習は「成績が一番良くなる場所へ坂を下る」イメージ。全データで一歩ずつだと重いので、データを小分け(ミニバッチ)にして、こまめに何度も一歩を進める。これがSGD。", "eg": "全教科まとめて復習してから直すのではなく、少しずつ小テストしては直す、を高速で繰り返す、あの進め方。", "terms": [["確率的勾配降下法（SGD）", "データを小分けにして、少しずつ何度も重みを更新する基本の最適化"], ["ミニバッチ", "一度の更新に使うデータの小さなかたまり"]], "think": "「データを小分けにしてこまめに更新」ならSGD。AdamなどはこのSGDに勢いや歩幅調整を足した発展形。", "vs": "主成分分析は次元削減、k近傍法は近所の正解で多数決する分類、焼きなまし法はわざと悪い方へも動く別の最適化。どれもミニバッチで重みを更新する基本の最適化ではない。", "usecase": "ディープラーニングの学習の土台。大量データでも現実的な速さで学習を進められる。Adamなどの発展形もこの上に乗る。", "opt": ["正解。データを小分けにして少しずつ重みを更新するのがSGD。", "次元削減の手法で、重みを更新する最適化ではない。", "近所の正解で多数決する分類で、最適化ではない。", "わざと悪い方へも動く別の最適化で、ミニバッチ更新ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='4. ディープラーニングの概要'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q21', '一回の更新で重みをどれだけ大きく動かすかを決める値で、大きすぎると答えを飛び越して発散し、小さすぎると学習が遅い。この値はどれか。', NULL, '["学習率", "バッチサイズ", "エポック数", "正則化係数"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "一回の更新で重みをどれだけ動かすか(歩幅)を決める値は？", "point": "「一回の更新で重みをどれだけ動かすか(歩幅)を決める値」なら、学習率。", "kid": "学習は坂を下るイメージ。その“一歩の大きさ”が学習率。大きすぎると谷を飛び越えて行ったり来たり(発散)、小さすぎるとなかなか下りきらない(遅い)。ちょうど良い歩幅が大事。", "eg": "山を下りるときの歩幅。大股すぎると転げ落ち、ちょこちょこ過ぎると日が暮れる。", "terms": [["学習率", "一回の更新で重みをどれだけ動かすかを決める値(歩幅)"], ["発散", "学習率が大きすぎて、答えに近づくどころか値が振れて壊れてしまうこと"]], "think": "「更新の歩幅・大きすぎると発散、小さすぎると遅い」なら学習率。何回データを回すか(エポック)や小分けの大きさ(バッチサイズ)とは別物。", "vs": "バッチサイズは一度の更新に使うデータ量、エポック数は全データを何周するか、正則化係数は過学習をどれだけ抑えるかの強さ。どれも一歩の歩幅を決める学習率ではない。", "usecase": "学習がうまくいかないとき最初に見直す設定。大きすぎ(発散)・小さすぎ(停滞)を避け、適切な歩幅に調整するのが学習成功の鍵。", "opt": ["正解。更新の歩幅を決めるのが学習率。", "一度の更新に使うデータ量のことで、歩幅そのものではない。", "全データを何周するかの回数で、一歩の大きさではない。", "過学習を抑える強さで、更新の歩幅ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='4. ディープラーニングの概要'
