INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q22', '学習を続けるうちに、訓練データの成績は上がり続けても検証データの成績が悪化し始めたら、そこで学習を打ち切る過学習対策はどれか。', NULL, '["早期終了（early stopping）", "ドロップアウト", "バッチ正規化", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "検証データの成績が悪化し始めたら学習を打ち切る過学習対策は？", "point": "「検証データの成績が下がり始めた所で学習を止める」なら、早期終了。", "kid": "学習を続けすぎると、訓練データを丸暗記して初見に弱くなる(過学習)。そこで、別に取っておいた検証データの成績が下がり始めたら「ここが潮時」と学習を止める。", "eg": "筋トレのやりすぎで逆に調子を崩す前に切り上げるように、伸びが止まった瞬間にやめる、あの見極め。", "terms": [["早期終了（early stopping）", "検証データの成績が悪化し始めた時点で学習を打ち切り、過学習を防ぐ手法"], ["過学習", "訓練データに合わせすぎて、初見のデータで成績が落ちる状態"]], "think": "「検証成績が悪化し始めたら止める」なら早期終了。ノードを休ませる(ドロップアウト)や値をそろえる(バッチ正規化)とは、やり方が違う過学習対策。", "vs": "ドロップアウトはノードをランダムに休ませる、バッチ正規化は各層の値をそろえる、データ拡張はデータを水増しする。どれも「悪化し始めたら止める」早期終了ではない。", "usecase": "追加のコストなしで過学習を防げる手軽な方法。学習の回しすぎによる劣化を避けるため、広く併用される。", "opt": ["正解。検証成績が悪化し始めた所で学習を止めるのが早期終了。", "ノードをランダムに休ませる別の過学習対策で、学習を止めるものではない。", "各層の値をそろえる手法で、学習を打ち切るものではない。", "データを水増しする手法で、早期終了とは別。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='4. ディープラーニングの概要'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q23', '分類問題で、モデルが出した確率が正解からどれだけずれているかを測り、学習の目印にする代表的な誤差（損失関数）はどれか。', NULL, '["交差エントロピー誤差", "平均二乗誤差", "マンハッタン距離", "コサイン類似度"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "分類で、出した確率が正解からどれだけずれているかを測る代表的な誤差は？", "point": "「分類で、確率が正解からどれだけずれたかを測る誤差」なら、交差エントロピー誤差。", "kid": "学習は「間違いの大きさ(誤差)」を小さくする方向に進む。分類では、モデルが出した確率が正解からどれだけ外れているかを測る“交差エントロピー”をその誤差に使うのが定番。", "eg": "テストの採点で、正解に自信満々で外したときほど大きく減点する、あの厳しめの採点方式。", "terms": [["交差エントロピー誤差", "分類で、予測確率が正解からどれだけずれているかを測る誤差。学習の目印にする"], ["平均二乗誤差", "予測した数値と正解の差を二乗して測る誤差。数値予測(回帰)で使う"]], "think": "「分類で確率のずれを測る誤差」なら交差エントロピー。数値そのものを当てる回帰では平均二乗誤差、と用途で使い分ける。", "vs": "平均二乗誤差は数値予測(回帰)用の誤差、マンハッタン距離やコサイン類似度は2つの近さを測る指標で、分類の学習誤差として標準で使うものではない。", "usecase": "画像分類や文章分類など、確率で答えるモデルの学習でほぼ標準の誤差。学習が「何を小さくしようとしているか」を決める重要な部品。", "opt": ["正解。分類で確率のずれを測る誤差が交差エントロピー。", "数値予測(回帰)で使う誤差で、分類の確率のずれには標準で使わない。", "2点の近さを測る距離で、分類の学習誤差ではない。", "2つの向きの近さを測る指標で、分類の学習誤差ではない。"]}'::jsonb, 1
