SELECT s.id, c.id, 'g-kentei-b-q25', '層をいくつか飛び越えて入力をそのまま先の層へ足し込む近道を作り、非常に深いネットワークでも学習できるようにした仕組みはどれか。', NULL, '["残差接続（スキップ結合）", "ドロップアウト", "プーリング", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "層を飛び越えて入力を先へ足し込む近道を作り、深いネットワークを学習可能にした仕組みは？", "point": "「層を飛び越えて入力を先へ足し込む“近道”で、深くても学習できる」なら、残差接続(スキップ結合)。", "kid": "層をたくさん重ねると、学習の「直してね」の合図が奥まで届かず学べなくなる。そこで、途中をショートカットして入力をそのまま先へ足す“近道”を作ると、合図が消えずに届き、とても深いネットワークでも学習できる。", "eg": "長い階段の横にエレベーター(近道)を付けるように、遠い層へ信号がそのまま届く抜け道を用意する。", "terms": [["残差接続（スキップ結合）", "層を飛び越えて入力を先の層へ足す近道。深いネットワークの学習を可能にした"], ["ResNet", "残差接続を使い、100層を超える深さでも学習できるようにした画像認識モデル"]], "think": "「層を飛び越える近道で深くても学習できる」なら残差接続。勾配消失(信号が奥まで届かない)を、経路を足すことで和らげる工夫。", "vs": "ドロップアウトはノードを休ませる過学習対策、プーリングは特徴を縮める操作、データ拡張はデータの水増し。どれも層を飛び越える近道ではない。", "usecase": "超深層のネットワークを実現した鍵で、画像認識のResNetが代表。今の多くの大規模モデルにも取り入れられている。", "opt": ["正解。層を飛び越える近道で深くても学習できるのが残差接続。", "ノードを休ませる過学習対策で、層を飛び越える近道ではない。", "特徴を縮める操作で、近道を作る仕組みではない。", "データを水増しする手法で、残差接続とは別。"]}'::jsonb, 1
