SELECT s.id, c.id, 'g-kentei-b-q26', '手元の画像を回転・反転・拡大などで少しずつ変形させ、学習用データを水増しして過学習を抑える手法はどれか。', NULL, '["データ拡張（Data Augmentation）", "転移学習", "アノテーション", "次元削減"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像を回転・反転などで変形して学習データを水増しする手法は？", "point": "「手元のデータを変形して水増しし、過学習を抑える」なら、データ拡張。", "kid": "データが少ないと丸暗記(過学習)しやすい。そこで、同じ画像を少し回したり反転したりして“別の一枚”を作り、水増しする。見え方の違いに強いモデルになる。", "eg": "一枚の写真を、傾けたり左右反転したりして「いろんな角度から見た別の写真」に増やす、あの発想。", "terms": [["データ拡張（Data Augmentation）", "既存データを回転・反転などで変形し、学習データを水増しして過学習を抑える手法"], ["過学習", "訓練データに合わせすぎて、初見のデータで成績が落ちる状態"]], "think": "「既存データを変形して水増し」ならデータ拡張。学習済みモデルを流用する転移学習や、正解を付けるアノテーションとは別のアプローチ。", "vs": "転移学習は学習済みの知識を別タスクに使い回す考え方、アノテーションは正解ラベルを付ける作業、次元削減は項目の数を減らす手法。どれもデータを変形して水増しする手法ではない。", "usecase": "画像認識で少ないデータを補うほぼ定番の手法。回転や色変えに強い、頑丈なモデルを作れる。", "opt": ["正解。既存データを変形して水増しし過学習を抑えるのがデータ拡張。", "学習済みの知識を別タスクに使い回す考え方で、水増しそのものではない。", "正解ラベルを付ける作業で、データの変形ではない。", "項目の数を減らす手法で、データの水増しではない。"]}'::jsonb, 1
