SELECT s.id, c.id, 'g-kentei-b-q27', '前の層の全てのノードと、次の層の全てのノードを一つ残らずつなぎ、入力全体をまとめて処理する層はどれか。', NULL, '["全結合層", "畳み込み層", "プーリング層", "回帰結合層"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "前の層と次の層の全ノードを残らずつなぎ、入力全体をまとめて処理する層は？", "point": "「前後の層の全ノードを一つ残らずつなぐ」なら、全結合層。", "kid": "前の層の出力を全部、次の層の全部のノードにつなぐ層。入力のどこも見落とさずまとめて扱えるが、つなぎが多い分だけ計算や覚える数(重み)も多くなる。", "eg": "全員が全員と握手する懇親会のように、片側の全員をもう片側の全員につなぐ、あの密なつなぎ方。", "terms": [["全結合層", "前の層の全ノードを次の層の全ノードにつなぐ層。入力全体をまとめて扱う"], ["畳み込み層", "小さなフィルタを使い回して局所の特徴だけを拾う、つなぎを絞った層"]], "think": "「全ノードを残らずつなぐ」なら全結合層。フィルタを使い回して一部だけつなぐ畳み込み層とは、つなぎ方が対照的。", "vs": "畳み込み層はフィルタで局所だけを拾う層、プーリング層は特徴を縮める操作、回帰結合層は系列を順に処理する層。どれも全ノードを残らずつなぐ全結合層ではない。", "usecase": "分類の出口など「集めた特徴を最終的にまとめて判断する」段で使う。画像では畳み込みで特徴を絞った後、最後に全結合層で判定することが多い。", "opt": ["正解。前後の層の全ノードを残らずつなぐのが全結合層。", "フィルタで局所だけを拾う層で、全ノードをつなぐわけではない。", "特徴を縮める操作で、全ノードをつなぐ層ではない。", "系列を順に処理する層で、全結合とは仕組みが違う。"]}'::jsonb, 1
