INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q28', '翻訳などで、出力する単語を決めるたびに、入力文のどの単語に注目すべきかを重み付けして参照する仕組みはどれか。', NULL, '["注意機構（Attention）", "プーリング", "ドロップアウト", "バッチ正規化"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "出力のたびに、入力のどの単語に注目すべきかを重み付けして参照する仕組みは？", "point": "「出力するたび、入力のどこに注目すべきかを重み付けして選ぶ」なら、注意機構(Attention)。", "kid": "翻訳で「次の単語」を出すたびに、入力文のどの単語が今いちばん関係あるかに“注目”して、そこを重点的に見る。関係の薄い所は軽く見る。この注目の重み付けがAttention。", "eg": "長文を訳すとき、今書いている部分に関係する原文の箇所を指でなぞりながら訳す、あの目の動き。", "terms": [["注意機構（Attention）", "出力のたびに入力のどこに注目すべきかを重み付けし、関係の深い部分を重点的に見る仕組み"], ["自己注意（Self-Attention）", "同じ文の中で単語どうしの関係を測るAttention。Transformerの中核"]], "think": "「出力のたびに入力のどこを見るか重み付け」ならAttention。同じ文の中の単語どうしを見るのが自己注意、入力と出力の間で見るのがこのソース・ターゲット型。", "vs": "プーリングは特徴を縮める操作、ドロップアウトはノードを休ませる過学習対策、バッチ正規化は各層の値をそろえる手法。どれも注目先を重み付けするAttentionではない。", "usecase": "機械翻訳の精度を大きく上げ、長い文でも関係する箇所を捉えられるようにした。Transformerや今のLLMの土台になった考え方。", "opt": ["正解。出力のたび入力のどこに注目するか重み付けするのがAttention。", "特徴を縮める操作で、注目先を重み付けする仕組みではない。", "ノードを休ませる過学習対策で、Attentionではない。", "各層の値をそろえる手法で、注目の重み付けではない。"]}'::jsonb, 1
