INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q29', 'LSTMと同じく長い系列の情報を保てるが、内部の門（ゲート）を減らして構造を簡単にし、計算を軽くした手法はどれか。', NULL, '["GRU", "CNN", "SVM", "PCA"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "LSTMを簡単にして門を減らし、計算を軽くした系列処理の手法は？", "point": "「LSTMの門を減らして構造を簡単にし、計算を軽くした」なら、GRU。", "kid": "LSTMは「覚える・忘れる・思い出す」の門で長い情報を保つが、部品が多め。GRUは門を減らして仕組みを簡単にし、似た効果を保ちつつ計算を軽くした改良版。", "eg": "多機能リモコンのボタンを減らして、必要な機能はそのままに使いやすくした簡易版、あのイメージ。", "terms": [["GRU", "LSTMより門(ゲート)を減らして簡単にした、系列を扱う手法。計算が軽い"], ["LSTM", "門と記憶で長い系列の情報を保つ、RNNの改良版"]], "think": "「LSTMを簡単に・門が少なく・軽い」ならGRU。長い系列を扱う狙いはLSTMと同じで、構造を絞った点が違い。", "vs": "CNNは画像の局所特徴を拾う畳み込みのネットワーク、SVMは分ける線を学ぶ分類、PCAは次元削減。どれも系列を扱うLSTMの簡易版ではない。", "usecase": "LSTMより軽いので、計算資源が限られる場面や、まず手早く試したいときに向く。系列データの選択肢の一つ。", "opt": ["正解。LSTMの門を減らして簡単・軽くしたのがGRU。", "画像の局所特徴を拾うネットワークで、系列の簡易版ではない。", "分ける線を学ぶ分類で、系列処理の手法ではない。", "次元削減の手法で、LSTMの簡易版ではない。"]}'::jsonb, 1
