INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q30', '一枚の画像に対して「これは猫」「これは犬」のように、画像全体を表す一つのラベルを答えるタスクはどれか。', NULL, '["画像分類", "物体検出", "セマンティックセグメンテーション", "姿勢推定"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像全体に一つのラベルを答えるタスクは？", "point": "「画像全体に一つのラベルを答える(場所は出さない)」なら、画像分類。", "kid": "写真を一枚見せて「これは何?」に一言で答えるタスク。「猫」とだけ答え、どこにいるか(場所)は出さない。CNNの一番基本的な使い道。", "eg": "写真を見て「これは猫の写真」とアルバムに一枚だけタグを付ける、あの作業。", "terms": [["画像分類", "画像全体が何かを一つのラベルで答えるタスク。場所は出さない"], ["物体検出", "何が・どこにあるかを枠で囲んで同時に答える、一段細かいタスク"]], "think": "「画像全体に一つのラベル・場所は出さない」なら画像分類。枠で位置も出すのは物体検出、画素ごとに塗り分けるのはセグメンテーション。", "vs": "物体検出は種類と位置(枠)を同時に出す、セマンティックセグメンテーションは画素ごとにラベルを塗り分ける、姿勢推定は関節の位置を当てる。どれも画像全体への一ラベルではない。", "usecase": "不良品かどうかの判定、写真の自動タグ付けなど、「一枚が何か」を答えれば済む場面で使う。CNNの応用の入り口。", "opt": ["正解。画像全体に一つのラベルを答えるのが画像分類。", "種類と位置(枠)を同時に出すタスクで、一ラベルだけではない。", "画素ごとに塗り分けるタスクで、画像全体への一ラベルではない。", "関節の位置を当てるタスクで、画像全体の分類ではない。"]}'::jsonb, 1
