SELECT s.id, c.id, 'g-kentei-b-q31', '人が話した音声の波形を受け取り、その内容を文字（テキスト）に書き起こすタスクはどれか。', NULL, '["音声認識", "音声合成", "画像認識", "異常検知"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "話した音声を文字に書き起こすタスクは？", "point": "「音声を受け取って文字に書き起こす」なら、音声認識。", "kid": "マイクに入った声(音の波)を聞き取って、「おはよう」のような文字に直すタスク。声→文字の向き。逆に文字→声はまた別のタスク。", "eg": "会議の録音を聞きながら、文字起こしをしてくれる書記のような役割。", "terms": [["音声認識", "音声(音の波)を受け取り、内容を文字に書き起こすタスク。声→文字"], ["音声合成", "文字から人の声を作り出すタスク。音声認識と向きが逆"]], "think": "「音声を文字にする(声→文字)」なら音声認識。文字から声を作る音声合成とは向きが逆、と押さえる。", "vs": "音声合成は文字から声を作る(向きが逆)、画像認識は画像を扱う、異常検知はいつもと違うデータを見つける。どれも音声を文字に起こすタスクではない。", "usecase": "スマートスピーカーへの話しかけ、会議の自動文字起こし、音声入力などで使う身近な技術。", "opt": ["正解。音声を受け取って文字に書き起こすのが音声認識。", "文字から声を作るタスクで、向きが逆。", "画像を扱うタスクで、音声を文字にするものではない。", "いつもと違うデータを見つけるタスクで、音声の書き起こしではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='6. ディープラーニングの応用例'
