INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q32', '試行錯誤で良い行動を学ぶ強化学習に、ディープラーニングを組み合わせ、囲碁AIのAlphaGoやゲーム攻略で成果を上げた手法はどれか。', NULL, '["深層強化学習", "教師あり学習", "主成分分析", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "強化学習にディープラーニングを組み合わせた手法は？", "point": "「試行錯誤で行動を学ぶ強化学習＋ディープラーニング」なら、深層強化学習。", "kid": "ごほうび(報酬)を頼りに試行錯誤で行動を学ぶのが強化学習。そこに、状況を見て判断する目としてディープラーニングを組み合わせたのが深層強化学習。囲碁やゲームで人間超えを果たした。", "eg": "「経験から学ぶ勘(強化学習)」に「複雑な盤面を見抜く目(ディープラーニング)」を足した、あの組み合わせ。", "terms": [["深層強化学習", "強化学習(報酬で試行錯誤)とディープラーニングを組み合わせた手法"], ["強化学習", "行動の結果もらえる報酬を最大にするよう、試行錯誤で行動を学ぶ方法"]], "think": "「強化学習＋ディープラーニング」なら深層強化学習。報酬で学ぶ点は強化学習、複雑な状況を捉える目がディープラーニング、と分けて捉える。", "vs": "教師あり学習は入力と正解のセットで学ぶ、主成分分析は次元削減、データ拡張はデータの水増し。どれも強化学習にディープラーニングを組み合わせた手法ではない。", "usecase": "囲碁のAlphaGo、テレビゲームの攻略、ロボットの制御など、複雑な状況で一連の行動を学ぶ場面で成果を上げた。", "opt": ["正解。強化学習とディープラーニングを組み合わせたのが深層強化学習。", "入力と正解のセットで学ぶ方法で、報酬による試行錯誤ではない。", "次元削減の手法で、強化学習との組み合わせではない。", "データの水増しで、深層強化学習とは別。"]}'::jsonb, 1
