INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q33', '大きくて重い高性能モデルの判断を、小さなモデルにまねさせて学習させ、性能を保ちつつ軽くする手法はどれか。', NULL, '["蒸留（知識蒸留）", "データ拡張", "アノテーション", "交差検証"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大きなモデルの判断を小さなモデルにまねさせて軽くする手法は？", "point": "「大きなモデルの判断を小さなモデルにまねさせて軽くする」なら、蒸留(知識蒸留)。", "kid": "高性能だけど重いモデルは、スマホなどでは動かしにくい。そこで、その大きなモデルの答え方を“先生”として小さなモデルにまねさせ、性能を保ったまま軽くする。これが蒸留。", "eg": "名人の技を弟子が見て盗み、名人ほど大掛かりでなくても同じ味を出せるようにする、あの継承。", "terms": [["蒸留（知識蒸留）", "大きなモデルの出力を教師にして小さなモデルを学習させ、性能を保ちつつ軽くする手法"], ["モデルの軽量化", "蒸留・量子化・枝刈りなどで、モデルを小さく速くする取り組みの総称"]], "think": "「大モデルの判断を小モデルにまねさせて軽くする」なら蒸留。データを水増しするデータ拡張や、正解を付けるアノテーションとは目的が違う。", "vs": "データ拡張はデータを水増しする手法、アノテーションは正解ラベルを付ける作業、交差検証は評価の方法。どれもモデルを小さく軽くする蒸留ではない。", "usecase": "スマホや組み込み機器など、計算資源が限られる場所で高性能モデルを動かしたいときに使う。速度と性能の両立の一手。", "opt": ["正解。大モデルの判断を小モデルにまねさせて軽くするのが蒸留。", "データを水増しする手法で、モデルを軽くするものではない。", "正解ラベルを付ける作業で、軽量化ではない。", "評価の方法で、モデルを軽くする手法ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='6. ディープラーニングの応用例'
