INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q34', '画像と、それを説明する文章のように、種類の違う情報を一緒に扱えるようにしたAIを指す語はどれか。', NULL, '["マルチモーダル", "ユニモーダル", "アンサンブル", "オートエンコーダ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像と文章のように種類の違う情報を一緒に扱うAIを指す語は？", "point": "「画像・文章・音声など複数種類の情報を一緒に扱う」なら、マルチモーダル。", "kid": "これまでのAIは画像なら画像だけ、と一種類が普通だった。画像と文章を同時に結びつけて扱えるように、複数の種類(モード)の情報をまたいで扱うのがマルチモーダル。", "eg": "目(画像)と耳と言葉(文章)を同時に使って状況を理解する、人間のような情報の受け取り方。", "terms": [["マルチモーダル", "画像・文章・音声など、種類の違う情報を組み合わせて扱うこと"], ["CLIP", "画像と説明文を結びつけて学習した代表的なマルチモーダルモデル"]], "think": "「複数の種類(画像＋文章など)を一緒に扱う」ならマルチモーダル。一種類だけ扱うのがユニモーダル、と対で押さえる。", "vs": "ユニモーダルは一種類の情報だけを扱うこと、アンサンブルは複数モデルを組み合わせる手法、オートエンコーダは圧縮して復元を学ぶネットワーク。どれも複数種類の情報をまたいで扱うことそのものではない。", "usecase": "「写真に合う説明文を作る」「文章から画像を生成する」など、種類をまたぐAIの土台。今の生成AIの多くがこの方向に進んでいる。", "opt": ["正解。種類の違う情報を組み合わせて扱うのがマルチモーダル。", "一種類の情報だけを扱うことで、複数種類をまたぐ話ではない。", "複数モデルを組み合わせる手法で、情報の種類の話ではない。", "圧縮して復元を学ぶネットワークで、複数種類を扱うことそのものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='6. ディープラーニングの応用例'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q35', '大量のデータであらかじめ広く学習しておき、その後さまざまな用途に少しの調整で使い回せる、大規模で汎用的なモデルを指す語はどれか。', NULL, '["基盤モデル（ファウンデーションモデル）", "エキスパートシステム", "決定木", "混同行列"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大量データで広く事前学習し、さまざまな用途に使い回せる大規模で汎用的なモデルを指す語は？", "point": "「大量データで広く事前学習し、少しの調整で多用途に使い回せる大規模モデル」なら、基盤モデル。", "kid": "まず大量のデータで幅広く“基礎学力”をつけておく。あとは翻訳でも要約でも、少しの追加調整でいろんな仕事に使い回せる。この土台となる大規模モデルが基盤モデル。", "eg": "何にでも応用できる基礎学力を先につけておき、あとは各仕事に合わせて少し慣らすだけで働ける人材、あのイメージ。", "terms": [["基盤モデル（ファウンデーションモデル）", "大量データで広く事前学習し、微調整で多用途に使い回せる大規模モデル。GPTなどが代表"], ["ファインチューニング", "基盤モデルを土台に、特定タスク向けに少し追加学習して調整すること"]], "think": "「大量データで事前学習・多用途に使い回す土台」なら基盤モデル。個別に作り込む古いエキスパートシステムとは発想が逆。", "vs": "エキスパートシステムは人がルールを書く古典的な仕組み、決定木は条件分岐で予測する手法、混同行列は判定結果の集計表。どれも大規模で汎用的な基盤モデルではない。", "usecase": "GPTなどの大規模言語モデルが代表。ゼロから作らず基盤モデルを土台にすれば、少ないデータ・短い時間で多くの応用を作れる。", "opt": ["正解。広く事前学習して多用途に使い回せる大規模モデルが基盤モデル。", "人がルールを書く古典的な仕組みで、汎用の土台モデルではない。", "条件分岐で予測する手法で、基盤モデルではない。", "判定結果の集計表で、モデルの種類ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='6. ディープラーニングの応用例'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q36', '大規模言語モデルに、例を一つも見せずに指示文だけで新しいタスクをこなさせるやり方を指す語はどれか。', NULL, '["ゼロショット（zero-shot）", "アノテーション", "データ拡張", "ホールドアウト"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "例を見せず指示文だけで新しいタスクをこなさせるやり方は？", "point": "「例を一つも見せず、指示だけでタスクをこなさせる」なら、ゼロショット。", "kid": "ふつうは「こういう時はこう」という例をいくつか見せて覚えさせる。ゼロショットは、例をひとつも見せずに「〜して」と指示するだけでこなさせるやり方。例を数個見せる版はフューショット。", "eg": "お手本なしで「いい感じに要約して」と頼むだけで、それらしくやってくれる、あの器用さ。", "terms": [["ゼロショット（zero-shot）", "例を見せず、指示文だけで新しいタスクをこなさせるやり方"], ["フューショット（few-shot）", "例を数個だけ見せてタスクをこなさせるやり方"]], "think": "「例ゼロ・指示だけ」ならゼロショット。「例を数個見せる」ならフューショット、と例の数で見分ける。", "vs": "アノテーションは正解ラベルを付ける作業、データ拡張はデータの水増し、ホールドアウトは評価の分け方。どれも例なしで指示だけこなすやり方ではない。", "usecase": "大規模言語モデルに、追加学習なしでプロンプト(指示文)だけで多様な仕事をさせる使い方。手早く試せるので実務で多用される。", "opt": ["正解。例を見せず指示だけでこなさせるのがゼロショット。", "正解ラベルを付ける作業で、指示だけこなすやり方ではない。", "データの水増しで、ゼロショットとは別。", "評価の分け方で、タスクのこなし方ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='6. ディープラーニングの応用例'
