INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q37', 'データ分析プロジェクトを「業務理解→データ理解→データ準備→モデル作成→評価→展開」という段階で進める、代表的な進め方の型はどれか。', NULL, '["CRISP-DM", "MLOps", "PoC", "スクラム"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "データ分析プロジェクトを決まった段階で進める、代表的な型は？", "point": "「データ分析を業務理解から展開まで、決まった段階で進める型」なら、CRISP-DM。", "kid": "データ分析を行き当たりばったりでなく、「まず業務を理解、データを見る、準備、モデル作成、評価、展開」と決まった順番で進める、標準的な段取りの型。", "eg": "料理のレシピのように「下ごしらえ、調理、味見、提供」と手順を決めておき、迷わず進められるようにしたもの。", "terms": [["CRISP-DM", "データ分析プロジェクトを6段階で進める代表的な標準プロセス"], ["PoC", "本開発の前に小さく試して実現性を確かめる工程。CRISP-DMより手前の位置づけ"]], "think": "「データ分析を決まった段階で進める型」ならCRISP-DM。運用を継続的に回すMLOpsとは、指す範囲が違う。", "vs": "MLOpsは運用しながら継続的に回す実践、PoCは本開発前の小さな検証、スクラムはソフト開発の進め方(アジャイル)。どれもデータ分析専用の6段階プロセスそのものではない。", "usecase": "データ分析プロジェクトの計画・見積もりの共通言語として使う。どの段階にいるか・次に何をするかを関係者で揃えられる。", "opt": ["正解。データ分析を6段階で進める代表的な型がCRISP-DM。", "運用を継続的に回す実践で、分析の進め方の型そのものではない。", "本開発前の小さな検証で、全体の進め方の型ではない。", "ソフト開発の進め方で、データ分析専用の型ではない。"]}'::jsonb, 1
