SELECT s.id, c.id, 'g-kentei-b-q38', '収集したデータに含まれる、欠けている値・明らかな誤り・重複などを整えて、分析や学習に使える状態にする作業はどれか。', NULL, '["データクレンジング（データの前処理）", "デプロイ", "ハイパーパラメータ探索", "バックプロパゲーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "欠損・誤り・重複を整えて、データを使える状態にする作業は？", "point": "「欠けた値・誤り・重複を整えてデータを使える状態にする」なら、データクレンジング。", "kid": "集めたデータには、空欄や打ち間違い、同じ行の重複などが混じっている。そのままだと学習が歪むので、きれいに整える下ごしらえ。これがデータクレンジング。", "eg": "料理の前に野菜を洗って、傷んだ所や汚れを取り除く下ごしらえ、あの作業。", "terms": [["データクレンジング", "欠損値・誤り・重複などを整え、データを分析や学習に使える状態にする作業"], ["欠損値", "本来あるべき値が抜けている箇所。埋めるか除くかの判断が要る"]], "think": "「欠損や誤りを整える下ごしらえ」ならデータクレンジング。作ったモデルを動かすデプロイや、学習そのものとは別の工程。", "vs": "デプロイは作ったモデルを本番で動かすこと、ハイパーパラメータ探索は設定値の調整、バックプロパゲーションは学習の計算手法。どれもデータを整える前処理ではない。", "usecase": "「データの質が悪いと結果も悪い」を防ぐ、分析・学習の土台となる工程。実務では作業時間の大半を占めることも多い。", "opt": ["正解。欠損や誤り・重複を整えてデータを使える状態にするのがデータクレンジング。", "作ったモデルを本番で動かすことで、データを整える作業ではない。", "設定値の調整で、データの前処理ではない。", "学習の計算手法で、データを整えることではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='7. AIの社会実装に向けて'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
