INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q40', '迷惑メール判定で「大事な正常メールを誤って迷惑メール扱いする」ことを特に避けたい。このとき重視すべき指標はどれか。', NULL, '["適合率（Precision）", "再現率（Recall）", "学習率", "エポック数"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "誤検知(正常を誤って弾く)を特に避けたい場面で重視する指標は？", "point": "「誤検知(空振りで正常を弾く)を減らしたい」なら、適合率を高める。", "kid": "迷惑メール判定で怖いのは、大事な正常メールを誤って迷惑扱いすること(誤検知)。「迷惑と判定したもののうち、本当に迷惑だった割合」＝適合率を高めれば、この誤検知を減らせる。", "eg": "詐欺の通報で、無実の人を犯人扱いしないことを最優先する、あの慎重さ。誤って疑う“空振り”を減らす。", "terms": [["適合率（Precision）", "陽性と判定したうち、本当に陽性だった割合。誤検知(空振り)の少なさを表す"], ["再現率（Recall）", "本当に陽性のうち、正しく拾えた割合。見落としの少なさを表す"]], "think": "「誤検知(空振り)を減らしたい」なら適合率、「見落としを減らしたい」なら再現率。何を恐れる場面かで選ぶ。ここは正常メールを弾きたくない＝適合率。", "vs": "再現率は見落としを減らす指標(この場面の主役ではない)、学習率とエポック数は学習の設定値で、そもそも成績を測る指標ではない。", "usecase": "「間違って弾くと困る」場面(正常メール、健全な利用者の誤ブロックなど)で重視する。再現率とどちらを優先するか、場面で決める。", "opt": ["正解。誤検知(空振り)の少なさを表す適合率を高める。", "見落としを減らす指標で、誤検知を避けたい場面の主役ではない。", "学習の歩幅を決める設定で、成績を測る指標ではない。", "全データを何周するかの回数で、評価指標ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q41', '分類結果を「正解が陽性/陰性」×「予測が陽性/陰性」の4マスに集計し、当たり外れの内訳を一目で見られるようにした表はどれか。', NULL, '["混同行列", "相関行列", "ROC曲線", "ヒストグラム"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "分類の当たり外れの内訳を4マスに集計した表は？", "point": "「正解×予測の4マスで当たり外れの内訳を集計した表」なら、混同行列。", "kid": "分類の成績を「正解が陽性か陰性か」×「予測が陽性か陰性か」の4マスに数えて並べた表。どこで当たり、どこで外したか(見落としか誤検知か)が一目で分かる。適合率や再現率もここから計算する。", "eg": "テストの答え合わせを「合ってた/間違えた」×「自信あり/なし」の4マスに整理して、弱点を見える化する、あの表。", "terms": [["混同行列", "正解と予測を陽性/陰性で掛け合わせた4マスの表。当たり外れの内訳を示す"], ["適合率・再現率", "混同行列の4マスの数から計算する評価指標"]], "think": "「4マスで当たり外れの内訳を集計」なら混同行列。項目どうしの相関を並べる相関行列とは別物、と名前で混同しない。", "vs": "相関行列は項目どうしの相関を並べた表、ROC曲線は判定の線を動かしたときの成績の曲線、ヒストグラムはデータの分布を棒で見る図。どれも分類の4マス集計ではない。", "usecase": "分類モデルが「どのタイプの間違いをしているか(見落とし多め/誤検知多め)」を把握し、適合率・再現率を計算する土台。", "opt": ["正解。正解×予測の4マスで内訳を集計するのが混同行列。", "項目どうしの相関を並べた表で、分類の当たり外れの集計ではない。", "判定の線を動かしたときの成績の曲線で、4マスの表ではない。", "データの分布を棒で見る図で、分類結果の集計ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q42', '「アイスの売上が増えると水難事故も増える」というデータの関係について、最も適切な解釈はどれか。', NULL, '["同時に増えても、一方が他方の原因とは限らない", "アイスの売上が事故を直接引き起こしている", "水難事故が増えたことが売上を押し上げている", "二つの数字の間には全く関係が見られない"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "2つが一緒に増減しても、一方が他方の原因とは限らない。この考え方は？", "point": "「一緒に動いても、一方が他方の原因とは限らない」＝相関は因果ではない。", "kid": "アイスの売上と水難事故が同時に増えるのは、どちらも「暑さ」という共通の原因のせい。売上が事故を起こすわけではない。一緒に動くこと(相関)と、原因-結果(因果)は別、という話。", "eg": "背が高い人ほど足も大きいが、背が伸びたから足が大きいわけではなく、どちらも「成長」という共通の原因による、あの関係。", "terms": [["相関", "2つの量が一緒に増減する関係。原因-結果とは限らない"], ["因果", "一方が他方を引き起こす原因-結果の関係"]], "think": "「一緒に動く」だけでは因果とは言えない。隠れた共通の原因(この例では暑さ)がないか疑う、が判断のポイント。", "vs": "「一方が他方の直接の原因」と決めつける解釈は共通の原因を見落としている。「全く関係がない」も誤りで、相関自体はある。相関の有無と因果の有無は別々に考える。", "usecase": "データ分析で最も陥りやすい誤り。「相関があるから効果がある」と早合点しないための、意思決定の基本の心得。", "opt": ["正解。一緒に増減しても一方が他方の原因とは限らない。", "共通の原因(暑さ)を見落とした決めつけで、直接の原因とは言えない。", "因果の向きを逆にした決めつけで、これも直接の原因ではない。", "相関自体はあるので、全く関係がないとするのは誤り。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q43', '少数の極端に大きい値（外れ値）が混じったデータで、その影響を受けにくく、全体の「真ん中」をよく表すのはどれか。', NULL, '["中央値", "平均値", "合計値", "最大値"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "極端な外れ値の影響を受けにくく、真ん中をよく表すのは？", "point": "「極端な外れ値の影響を受けにくい“真ん中”」なら、中央値。", "kid": "平均は、一人だけ極端に大きい値があると、そちらへ引っ張られてしまう。中央値は「小さい順に並べた真ん中」なので、そういう極端な値に振り回されにくい。", "eg": "10人の年収に一人だけ億万長者が混じると、平均は跳ね上がるが、真ん中(中央値)はほぼ変わらない、あの差。", "terms": [["中央値", "データを小さい順に並べた真ん中の値。外れ値の影響を受けにくい"], ["平均値", "全部を足して個数で割った値。極端な外れ値に引っ張られやすい"]], "think": "「外れ値に強い真ん中」なら中央値。全部を足して割る平均値は、極端な値があると代表値としてずれる。データに外れ値がないか見て使い分ける。", "vs": "平均値は外れ値に引っ張られやすい、合計値はただの総和で真ん中を表さない、最大値は一番大きい値で真ん中ではない。どれも外れ値に強い真ん中ではない。", "usecase": "年収・地価など一部に極端な値があるデータで、実感に近い“真ん中”を示すのに使う。平均だけ見て誤解しないための基本。", "opt": ["正解。小さい順の真ん中で、外れ値の影響を受けにくいのが中央値。", "極端な値に引っ張られやすく、外れ値があると代表値がずれる。", "ただの総和で、真ん中を表す指標ではない。", "一番大きい値で、真ん中ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q44', '新しい技術的な発明について、出願して認められると、一定期間その発明を独占的に使える権利はどれか。', NULL, '["特許権", "営業秘密", "著作権", "商標権"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "発明を出願・登録して、一定期間独占的に使える権利は？", "point": "「発明を出願・公開して、一定期間の独占権をもらう」なら、特許権。", "kid": "新しい発明を国に出願して認められると、一定期間(原則20年)、その発明を独り占めで使える権利がもらえる。代わりに発明の中身は公開される。「公開して守ってもらう」制度。", "eg": "新しい料理法を役所に登録して「一定期間はうちだけ」と認めてもらう代わりに、レシピは公開する、あの取り引き。", "terms": [["特許権", "発明を出願・公開する代わりに、一定期間その発明を独占できる権利"], ["営業秘密", "公開せず秘密のまま守る枠組み。特許とは逆の発想"]], "think": "「出願・公開して独占権をもらう」なら特許権。秘密のまま守る営業秘密とは正反対、と押さえる。", "vs": "営業秘密は公開せず秘密のまま守る枠組み(逆の発想)、著作権は表現を守る権利、商標権は商品やサービスの目印を守る権利。どれも発明の独占権である特許権ではない。", "usecase": "AIの新しいアルゴリズムや技術を、公開してでも独占して守りたいときの選択肢。秘密のまま守る営業秘密と、どちらで守るかを選ぶ。", "opt": ["正解。発明を出願・公開して一定期間独占できるのが特許権。", "公開せず秘密のまま守る枠組みで、出願・公開する特許とは逆。", "表現を守る権利で、発明の独占権ではない。", "商品やサービスの目印を守る権利で、特許権ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q45', '巨大なIT企業が持つ大量のデータや市場での強い立場を使って、公正な競争を妨げる行為を規制する法律はどれか。', NULL, '["独占禁止法", "著作権法", "不正競争防止法", "特許法"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "強い立場を使って公正な競争を妨げる行為を規制する法律は？", "point": "「公正な競争を妨げる行為(市場の独占など)を規制する」なら、独占禁止法。", "kid": "一社が強すぎる立場やデータを使って、他社が入れないようにしたり不当に取引を縛ったりすると、競争が働かず利用者が損をする。それを防ぐのが独占禁止法。", "eg": "大人が一人で遊具を独り占めして他の子を入れないのを、先生が「みんなで公平に」と止める、あのルール。", "terms": [["独占禁止法", "市場の独占や不当な取引制限など、公正な競争を妨げる行為を規制する法律"], ["不正競争防止法", "営業秘密の侵害やまね(模倣)など、不正な競争行為を規制する別の法律"]], "think": "「公正な競争を妨げる行為(独占・不当な取引制限)の規制」なら独占禁止法。データやプラットフォームの独占が問題になる文脈で問われる。", "vs": "著作権法は表現を守る法律、不正競争防止法は営業秘密の侵害などを規制する法律、特許法は発明を守る法律。どれも公正な競争そのものを守る独占禁止法ではない。", "usecase": "大量データを握る巨大IT企業(プラットフォーマー)の振る舞いを問題にするときの根拠。AIとデータ独占をめぐる議論で登場する。", "opt": ["正解。公正な競争を妨げる行為を規制するのが独占禁止法。", "表現を守る法律で、競争を守るものではない。", "営業秘密の侵害などを規制する法律で、市場の独占規制そのものではない。", "発明を守る法律で、公正な競争を守るものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q46', '企業がAIサービスを外部に提供する契約で、出力の精度について実務上とられる考え方として最も適切なものはどれか。', NULL, '["精度は100%保証せず、責任の範囲を契約で定めておくのが一般的", "提供者が常に100%の精度を保証する義務を負うとされる", "精度に関する取り決めは法律で一律に決められている", "利用者は出力の結果に一切責任を負わなくてよい"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIサービス提供契約で、出力の精度についての実務上の考え方は？", "point": "「AIは確率的だから精度は100%保証せず、責任範囲を契約で定める」が実務。", "kid": "AIの出力は必ず当たるとは限らない(確率的)。だから提供する側は「精度は保証しません」「使い方はこの範囲で」と、責任の線引きを契約(利用規約)で決めておくのがふつう。", "eg": "天気予報サービスが「予報が外れても責任は負いません」と最初に断っておく、あの取り決めに近い。", "terms": [["AIサービス提供契約", "AIを外部提供する際に、精度の非保証や責任の範囲などを定める契約(利用規約)"], ["確率的", "AIの出力は必ず正しいとは限らず、確率的に外れることがある性質"]], "think": "「精度は保証しない・責任は契約で線引き」が実務の考え方。100%保証や、法律で一律に決まるという思い込みを外す。", "vs": "「常に100%保証する義務」は非現実的で誤り、「法律で一律に決まる」も誤り(契約で定める)、「利用者は一切責任を負わない」も誤りで、使い方次第で利用者側の責任もある。", "usecase": "AIサービスを作って提供する・導入する双方で、トラブル時の責任をあらかじめ決めておくために重要。過度な精度期待を避ける線引き。", "opt": ["正解。精度は保証せず、責任の範囲を契約で定めておくのが実務。", "AIは確率的に外れるため、常に100%保証する義務とするのは非現実的。", "精度の取り決めは契約で定めるもので、法律で一律ではない。", "使い方次第で利用者側の責任もあり、一切負わないは誤り。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q47', '過去の採用データで学習したAIが、そのデータに含まれていた男女の偏りをそのまま引き継ぎ、特定の性別を不利に扱ってしまう問題を指す語はどれか。', NULL, '["バイアス（学習データの偏りによる不公平）", "ハルシネーション", "過学習", "次元の呪い"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "学習データの偏りを引き継いで、特定の属性を不利に扱ってしまう問題は？", "point": "「学習データの偏りを引き継いで、特定の属性に不公平になる」なら、バイアス(公平性の問題)。", "kid": "AIは過去のデータをまねて学ぶ。だから、過去に男性ばかり採用していたデータで学べば「女性を低く評価する」偏りまで引き継いでしまう。この不公平がAIのバイアス。", "eg": "偏った先輩のやり方をそのまま覚えた新人が、同じ偏見で判断してしまう、あの引き継ぎ。", "terms": [["バイアス（公平性）", "学習データに含まれる偏りをAIが引き継ぎ、特定の属性に不公平な判断をする問題"], ["公平性", "性別や人種などで不当に差をつけない、というAI倫理の重要な価値"]], "think": "「データの偏りを引き継いで不公平になる」ならバイアス(公平性の問題)。事実に反する出力(ハルシネーション)や、訓練に合わせすぎる過学習とは別の論点。", "vs": "ハルシネーションは事実に反する出力をする現象、過学習は訓練データに合わせすぎる状態、次元の呪いは項目が多すぎてデータがスカスカになる問題。どれも学習データの偏りによる不公平ではない。", "usecase": "採用・与信・司法などAIの判断が人生に関わる場面で、差別を生まないために対策が必須。学習データの偏りの点検や、公平性の評価につながる。", "opt": ["正解。学習データの偏りを引き継いで不公平な判断をするのがバイアス。", "事実に反する出力をする現象で、偏りによる不公平とは別。", "訓練データに合わせすぎる状態で、公平性の問題ではない。", "項目が多すぎてデータがスカスカになる問題で、偏りの引き継ぎではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q48', '学習に使うデータにあらかじめ悪意のある例を紛れ込ませ、モデルを学習の段階から狂わせる攻撃はどれか。', NULL, '["データポイズニング", "敵対的サンプル", "ディープフェイク", "フィルターバブル"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "学習データに悪意ある例を紛れ込ませ、学習の段階からモデルを狂わせる攻撃は？", "point": "「学習データを汚して、学習の段階からモデルを狂わせる」なら、データポイズニング。", "kid": "AIは学習データをまねる。だから、そのデータにこっそり悪意ある例(毒)を混ぜておくと、モデルは最初から間違った覚え方をしてしまう。この“学習を汚す”攻撃がデータポイズニング。", "eg": "教科書に嘘のページを紛れ込ませて、生徒が最初から間違って覚えるように仕向ける、あの妨害。", "terms": [["データポイズニング", "学習データに悪意ある例を混ぜ、学習の段階からモデルを汚染する攻撃"], ["敵対的サンプル", "学習後、使うときの入力に小さなノイズを混ぜて誤らせる別の攻撃"]], "think": "「学習データを汚す(学習の段階の攻撃)」ならデータポイズニング。使うとき(推論時)の入力を細工する敵対的サンプルとは、狙う段階が違う。", "vs": "敵対的サンプルは使うときの入力を細工する攻撃、ディープフェイクは本物そっくりの偽コンテンツを作る技術、フィルターバブルは好みの情報に囲まれる現象。どれも学習データを汚す攻撃ではない。", "usecase": "ネットから集めたデータで学習するときのリスク。データの出所の確認や検査が防御になる、AIの安全性の論点。", "opt": ["正解。学習データを汚して学習の段階からモデルを狂わせるのがデータポイズニング。", "使うときの入力を細工する攻撃で、学習データを汚すのとは段階が違う。", "本物そっくりの偽コンテンツを作る技術で、学習を汚す攻撃ではない。", "好みの情報に囲まれる現象で、攻撃ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q49', '日本政府が示した、AIを社会で使う上での基本的な考え方をまとめた原則で、「AIは人間の尊厳を大切にし、人間が主体であるべき」といった方針を掲げるものはどれか。', NULL, '["人間中心のAI社会原則", "ムーアの法則", "ロボット工学三原則", "ベイズの定理"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "日本政府が示した、AIを社会で使う上での基本方針をまとめた原則は？", "point": "「日本政府が示した、人間が主体・人間の尊厳を大切に、というAIの基本原則」なら、人間中心のAI社会原則。", "kid": "AIをどう社会で使うべきかについて、日本政府が「AIは人間の尊厳を守り、人間が主役であるべき」といった考え方をまとめた指針。技術の話ではなく、社会での向き合い方の原則。", "eg": "学校の「みんなが安心して過ごすための約束ごと」のような、AIと社会のための基本ルール集。", "terms": [["人間中心のAI社会原則", "日本政府が示した、AIを社会で使う上での基本原則。人間の尊厳や主体性を重んじる"], ["AI事業者ガイドライン", "開発者・提供者・利用者それぞれの取るべき行動を示した、より実務寄りの指針"]], "think": "「日本政府・AIと社会・人間が主体」なら人間中心のAI社会原則。技術法則(ムーアの法則)やSFの創作(ロボット工学三原則)とは種類が違う。", "vs": "ムーアの法則は半導体の性能向上の経験則、ロボット工学三原則はSF作家アシモフの創作、ベイズの定理は確率を更新する数学の定理。どれも日本政府のAI社会原則ではない。", "usecase": "企業や行政がAIを導入する際の、倫理・ガバナンスの拠り所。「人間が主体」という軸を、方針づくりの土台にできる。", "opt": ["正解。日本政府が示した、人間を主体に置くAIの基本原則。", "半導体の性能向上の経験則で、社会原則ではない。", "SF作家の創作上の原則で、政府の社会原則ではない。", "確率を更新する数学の定理で、AIの社会原則ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-b-q50', 'SNSなどで、自分と同じ意見の人ばかりとつながるうちに、その意見だけが繰り返し響いて、まるで世の中全体がそう考えているかのように感じてしまう現象はどれか。', NULL, '["エコーチェンバー", "フィルターバブル", "フレーム問題", "シンギュラリティ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "同じ意見の人ばかりとつながり、その意見だけが響いて世の中全体がそう思っていると錯覚する現象は？", "point": "「同じ意見の人ばかりの中で、その意見だけが反響して増幅される」なら、エコーチェンバー。", "kid": "SNSで同じ意見の人ばかりフォローしていると、その意見だけが何度も返ってくる。すると、まるで世の中みんながそう考えているように錯覚してしまう。閉じた部屋で声が反響するイメージから、エコーチェンバー(反響室)と呼ぶ。", "eg": "洞窟の中で叫ぶと自分の声ばかり跳ね返ってきて、それが正しいと錯覚する、あの反響。", "terms": [["エコーチェンバー", "同じ意見の人ばかりの空間で、その意見が反響し増幅され、偏りが強まる現象"], ["フィルターバブル", "おすすめの仕組みが好みの情報ばかり見せ、視野が狭まる似た現象"]], "think": "「同じ意見どうしで反響して増幅」ならエコーチェンバー。おすすめ機能に囲い込まれるのがフィルターバブルで、原因が「人のつながり」か「おすすめの仕組み」かで区別すると分かりやすい。", "vs": "フィルターバブルはおすすめが好みの情報で囲い込む現象(似ているが原因が推薦の仕組み側)、フレーム問題は考える範囲を絞れない難問、シンギュラリティはAIが人間を超える未来。後ろ2つは情報の偏りの現象ですらない。", "usecase": "SNSでの意見の分断や過激化を説明する言葉。健全な情報環境の設計や、多様な意見に触れる工夫を考えるときの論点。", "opt": ["正解。同じ意見どうしで反響し増幅されるのがエコーチェンバー。", "おすすめが好みの情報で囲い込む似た現象で、原因が推薦の仕組み側。", "考える範囲を絞れない難問で、情報の偏りの現象ではない。", "AIが人間を超える未来のことで、情報の偏りとは関係ない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-b' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
COMMIT;
